	payloadLen := MaxPayload + 1
	buf := make([]byte, HeaderSize+payloadLen)
	binary.BigEndian.PutUint32(buf[0:4], uint32(payloadLen))
	buf[4] = 1
	binary.BigEndian.PutUint16(buf[8:10], refChecksum(t, buf, payloadLen))
