133	// buildFrame assures a wire frame with the given fields, recomputing the
134	// checksum so the caller can then corrupt it deliberately.
135	func buildFrame(t *testing.T, version uint8, flags uint16, kind uint8, payload []byte) []byte {
136		t.Helper()
137		buf := make([]byte, HeaderSize+len(payload))
138		binary.BigEndian.PutUint32(buf[0:4], uint32(len(payload)))
139		buf[4] = version
140		binary.BigEndian.PutUint16(buf[5:7], flags)
141		buf[7] = kind
142		copy(buf[HeaderSize:], payload)
143		binary.BigEndian.PutUint16(buf[8:10], refChecksum(t, buf, len(payload)))
144		return buf
